import{_ as r,o as t,c as a,a0 as e}from"./chunks/framework.DQOulFGV.js";const u=JSON.parse('{"title":"快速抓起喵 🐾","description":"","frontmatter":{},"headers":[],"relativePath":"meow/guide/start.md","filePath":"meow/guide/start.md"}'),l={name:"meow/guide/start.md"};function n(s,o,i,d,g,c){return t(),a("div",null,[...o[0]||(o[0]=[e('<h1 id="快速抓起喵-🐾" tabindex="-1">快速抓起喵 🐾 <a class="header-anchor" href="#快速抓起喵-🐾" aria-label="Permalink to &quot;快速抓起喵 🐾&quot;">​</a></h1><p>欢迎主人来到 <strong>KernelEX</strong> 喵！本喵会一步步带领主人了解猫窝环境要求、授权流程，以及怎样运行主人的第一个脚本喵~</p><hr><h2 id="📱-猫窝运行环境要求喵" tabindex="-1">📱 猫窝运行环境要求喵 <a class="header-anchor" href="#📱-猫窝运行环境要求喵" aria-label="Permalink to &quot;📱 猫窝运行环境要求喵&quot;">​</a></h2><p>在开始之前，请主人确认设备满足以下条件喵：</p><ul><li><strong>系统版本</strong>：Android 8.0 (API 26) 及以上喵</li><li><strong>设备架构</strong>：<code>arm64-v8a</code>、<code>armeabi-v7a</code>、<code>x86_64</code> 都支持喵</li><li><strong>ROOT 方案</strong>：已经安装好 <strong>Magisk</strong>、<strong>KernelSU</strong> 或 <strong>APatch</strong> 超级大管家喵</li><li><strong>存储权限</strong>：Android 11+ 设备需要给本喵「管理所有文件」权限，方便本喵帮主人读取外部存储里的脚本喵~</li></ul><hr><h2 id="🔑-权限配置指引喵" tabindex="-1">🔑 权限配置指引喵 <a class="header-anchor" href="#🔑-权限配置指引喵" aria-label="Permalink to &quot;🔑 权限配置指引喵&quot;">​</a></h2><p>主人第一次抱起 KernelEX 时，会看到可爱的**权限检查门（Permission Gate）**喵：</p><ol><li><strong>ROOT 超级权限</strong>：主人点击「请求 ROOT 授权」，在大管家（Magisk/KernelSU/APatch）弹窗里选择「永久允许」即可喵！</li><li><strong>所有文件管理权限</strong>：主人点击前往系统设置，开启文件管理开关，本喵就能帮主人找到藏在手机各处的脚本喵~</li><li><strong>忽略电池优化（本喵强烈推荐开启）</strong>：申请加入系统白名单，这样即使主人把手机塞进口袋，后台任务也不会被无情查杀喵！</li></ol><div class="tip custom-block"><p class="custom-block-title">自动感知喵</p><p>当所有必要权限都备齐之后，本喵就会自动感知并带主人进入主界面，完全不需要主人费心反复手动刷新喵~</p></div><hr><h2 id="🚀-运行主人的第一个脚本喵" tabindex="-1">🚀 运行主人的第一个脚本喵 <a class="header-anchor" href="#🚀-运行主人的第一个脚本喵" aria-label="Permalink to &quot;🚀 运行主人的第一个脚本喵&quot;">​</a></h2><p>本喵为主人准备了三种超级方便的执行姿势喵：</p><h3 id="姿势-1-首页直接输入或挑选喵" tabindex="-1">姿势 1：首页直接输入或挑选喵 <a class="header-anchor" href="#姿势-1-首页直接输入或挑选喵" aria-label="Permalink to &quot;姿势 1：首页直接输入或挑选喵&quot;">​</a></h3><ol><li>进入底栏「<strong>主页</strong>」喵；</li><li>在输入框填入脚本绝对路径，或者点击「<strong>从文件管理器选择</strong>」挑出 <code>.sh</code> 或 <code>.so</code> 目标文件喵；</li><li>点击「<strong>立即执行</strong>」，本喵就会立刻跳到「<strong>终端</strong>」把运行日志一条条递给主人看喵！</li></ol><h3 id="姿势-2-工作区秘密基地一键启动喵" tabindex="-1">姿势 2：工作区秘密基地一键启动喵 <a class="header-anchor" href="#姿势-2-工作区秘密基地一键启动喵" aria-label="Permalink to &quot;姿势 2：工作区秘密基地一键启动喵&quot;">​</a></h3><ol><li>把脚本直接丢进本喵的默认工作区：<code>/data/adb/KernelEX/</code> 喵；</li><li>在「主页」下方的小卡片里，主人轻轻一点就能直接选定或启动喵~</li></ol><h3 id="姿势-3-全盘文件页长按收纳喵" tabindex="-1">姿势 3：全盘文件页长按收纳喵 <a class="header-anchor" href="#姿势-3-全盘文件页长按收纳喵" aria-label="Permalink to &quot;姿势 3：全盘文件页长按收纳喵&quot;">​</a></h3><ol><li>切换到底栏「<strong>文件</strong>」页面喵；</li><li>找到目标脚本，长按它呼出爪爪菜单喵；</li><li>选择「<strong>添加到 KernelEX</strong>」，本喵会自动复制到工作区并加上 <code>chmod 777</code> 满权喵（如果在设置开启了「添加后自动执行」，还会立即为主人跑起来喵）！</li></ol><hr><h2 id="💻-终端操作与互动喵" tabindex="-1">💻 终端操作与互动喵 <a class="header-anchor" href="#💻-终端操作与互动喵" aria-label="Permalink to &quot;💻 终端操作与互动喵&quot;">​</a></h2><p>在「<strong>终端</strong>」页面，主人可以对本喵下达这些指令喵：</p><ul><li><strong>投喂输入（stdin）</strong>：如果脚本在等待主人回答输入，主人在底部输入栏打字并点击「发送」就可以投喂给它喵~</li><li><strong>轻挠中断（Ctrl+C）</strong>：点击「<strong>中断</strong>」按钮，本喵会给正在奔跑的子进程发送 <code>SIGINT</code>（<code>kill -2</code>）打断信号喵！</li><li><strong>强力按倒（结束进程）</strong>：点击「<strong>结束进程</strong>」强行拍灭顽固卡死任务（<code>kill -9</code>）喵。</li><li><strong>打包复制</strong>：点击顶部「<strong>复制输出</strong>」一键把控制台日志复制进主人的剪贴板喵。</li><li><strong>拍拍清屏与再跑一次</strong>：点击「<strong>清屏</strong>」把终端擦得干干净净，或者点「<strong>重新运行</strong>」让本喵再为主人跑一次上次的任务喵~</li></ul>',24)])])}const m=r(l,[["render",n]]);export{u as __pageData,m as default};
